struct Resource {
    int data = 42;
    Resource() = default;
};

// 1. Initial ownership
auto ptr_A = std::make_unique<Resource>();

// 2. Copy attempt fails (deleted function)
// auto ptr_B = ptr_A; // Error: Use of deleted function

// 3. Ownership transfer via move
auto ptr_B = std::move(ptr_A);

// 4. ptr_A is now null, ptr_B owns resource
if (!ptr_A) {
    ptr_B->data = 100;
}

// 5. Explicitly releasing ownership
Resource* raw_ptr = ptr_B.release();
delete raw_ptr;
